package com.example.circuitbreakerdemo.controller; import org.springframework.web.bind.annotation.*; import com.example.circuitbreakerdemo.service.OrderService; import com.example.circuitbreakerdemo.dto.PaymentResponse; @RestController public class OrderController{ private final OrderService s; public OrderController(OrderService s){this.s=s;} @GetMapping("/orders/{id}/payment") public PaymentResponse p(@PathVariable String id){return s.process(id);} }